#[cfg(windows)]
fn copy_to_clipboard(text: &str) {
    use std::ffi::OsStr;
    use std::os::windows::ffi::OsStrExt;

    extern "system" {
        fn OpenClipboard(hwnd: *mut std::ffi::c_void) -> i32;
        fn CloseClipboard() -> i32;
        fn EmptyClipboard() -> i32;
        fn SetClipboardData(format: u32, h_mem: *mut std::ffi::c_void) -> *mut std::ffi::c_void;
        fn GlobalAlloc(flags: u32, bytes: usize) -> *mut std::ffi::c_void;
        fn GlobalLock(h_mem: *mut std::ffi::c_void) -> *mut std::ffi::c_void;
        fn GlobalUnlock(h_mem: *mut std::ffi::c_void) -> i32;
    }

    let wide: Vec<u16> = OsStr::new(text).encode_wide().chain(std::iter::once(0)).collect();
    let bytes = wide.len() * 2;

    unsafe {
        if OpenClipboard(std::ptr::null_mut()) == 0 {
            return;
        }
        EmptyClipboard();
        let h_mem = GlobalAlloc(0x0042 /* GMEM_MOVEABLE | GMEM_ZEROINIT */, bytes);
        if !h_mem.is_null() {
            let ptr = GlobalLock(h_mem) as *mut u16;
            if !ptr.is_null() {
                std::ptr::copy_nonoverlapping(wide.as_ptr(), ptr, wide.len());
                GlobalUnlock(h_mem);
                SetClipboardData(13 /* CF_UNICODETEXT */, h_mem);
            }
        }
        CloseClipboard();
    }
}

#[cfg(not(windows))]
fn copy_to_clipboard(_text: &str) {}

struct BillingDb {
    conn: Connection,
}

impl BillingDb {
    fn new(db_path: &str) -> Result<Self, rusqlite::Error> {
        let conn = Connection::open(db_path)?;
        conn.execute_batch(
            "PRAGMA journal_mode = WAL;
             PRAGMA synchronous = NORMAL;
             CREATE TABLE IF NOT EXISTS license (
                 id INTEGER PRIMARY KEY,
                 plan TEXT NOT NULL,
                 plan_name TEXT NOT NULL,
                 license_key TEXT NOT NULL,
                 expires TEXT NOT NULL,
                 credits INTEGER NOT NULL,
                 max_credits INTEGER NOT NULL
             );
             CREATE TABLE IF NOT EXISTS ledger (
                 id INTEGER PRIMARY KEY AUTOINCREMENT,
                 timestamp TEXT NOT NULL,
                 action TEXT NOT NULL,
                 amount TEXT NOT NULL,
                 status TEXT NOT NULL
             );",
        )?;

        // Seed initial record if empty
        let count: i64 = conn.query_row("SELECT COUNT(*) FROM license", [], |r| r.get(0))?;
        if count == 0 {
            conn.execute(
                "INSERT INTO license (id, plan, plan_name, license_key, expires, credits, max_credits)
                 VALUES (1, 'free', 'Community Starter', 'LIC-ED25519-FREE-7482-COMMUNITY', 'Perpetual Lifetime', 1000, 1000);",
                [],
            )?;
            conn.execute(
                "INSERT INTO ledger (timestamp, action, amount, status)
                 VALUES ('2026-11-02 12:00:00', 'Initial Community Starter Allocation', '+1,000 Credits', 'INITIALIZED');",
                [],
            )?;
        }

        Ok(Self { conn })
    }

    fn get_license(&self) -> (String, String, String, String, i32, i32) {
        self.conn
            .query_row(
                "SELECT plan, plan_name, license_key, expires, credits, max_credits FROM license WHERE id = 1",
                [],
                |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?, r.get(3)?, r.get(4)?, r.get(5)?)),
            )
            .unwrap_or_else(|_| (
                "free".into(),
                "Community Starter".into(),
                "LIC-ED25519-FREE-7482".into(),
                "Perpetual Lifetime".into(),
                1000,
                1000,
            ))
    }

    fn update_credits(&self, new_credits: i32) -> Result<(), rusqlite::Error> {
        self.conn.execute("UPDATE license SET credits = ?1 WHERE id = 1", params![new_credits])?;
        Ok(())
    }

    fn upgrade_plan(&self, plan: &str, plan_name: &str, license_key: &str, expires: &str, new_credits: i32, max_credits: i32) -> Result<(), rusqlite::Error> {
        self.conn.execute(
            "UPDATE license SET plan = ?1, plan_name = ?2, license_key = ?3, expires = ?4, credits = ?5, max_credits = ?6 WHERE id = 1",
            params![plan, plan_name, license_key, expires, new_credits, max_credits],
        )?;
        Ok(())
    }

    fn add_ledger_entry(&self, timestamp: &str, action: &str, amount: &str, status: &str) -> Result<(), rusqlite::Error> {
        self.conn.execute(
            "INSERT INTO ledger (timestamp, action, amount, status) VALUES (?1, ?2, ?3, ?4)",
            params![timestamp, action, amount, status],
        )?;
        Ok(())
    }

    fn get_ledger(&self) -> Vec<LedgerEntry> {
        let mut stmt = match self.conn.prepare("SELECT id, timestamp, action, amount, status FROM ledger ORDER BY id DESC LIMIT 50") {
            Ok(s) => s,
            Err(_) => return Vec::new(),
        };

        let rows = stmt.query_map([], |r| {
            Ok(LedgerEntry {
                id: r.get(0)?,
                timestamp: r.get::<_, String>(1)?.into(),
                action: r.get::<_, String>(2)?.into(),
                amount: r.get::<_, String>(3)?.into(),
                status: r.get::<_, String>(4)?.into(),
            })
        });

        match rows {
            Ok(iter) => iter.filter_map(Result::ok).collect(),
            Err(_) => Vec::new(),
        }
    }
}

fn now_str() -> String {
    let now = std::time::SystemTime::now();
    let duration = now.duration_since(std::time::UNIX_EPOCH).unwrap_or_default();
    let secs = duration.as_secs();
    // Simplified human-readable UTC timestamp
    let s = secs % 60;
    let m = (secs / 60) % 60;
    let h = (secs / 3600) % 24;
    format!("2026-11-02 {:02}:{:02}:{:02} UTC", h, m, s)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let app = BillingHubWindow::new()?;
    let app_handle = app.as_weak();

    // In-process SQLite database in WAL mode
    let db = Arc::new(Mutex::new(BillingDb::new("billing_hub.db")?));

    // Load initial state into UI
    {
        let db_lock = db.lock().unwrap();
        let (plan, plan_name, key, expires, credits, max_credits) = db_lock.get_license();
        app.set_active_plan(plan.into());
        app.set_active_plan_name(plan_name.into());
        app.set_license_key(key.into());
        app.set_license_expires(expires.into());
        app.set_available_credits(credits);
        app.set_max_credits(max_credits);

        let entries = db_lock.get_ledger();
        let model = Rc::new(VecModel::from(entries));
        app.set_ledger_entries(model.into());
    }

    // 1. Task Credit Consumption (Simulate AI / GPU Job)
    {
        let app_weak = app_handle.clone();
        let db = Arc::clone(&db);
        app.on_consume_credits(move |amount| {
            let Some(ui) = app_weak.upgrade() else { return };
            let db_lock = db.lock().unwrap();
            let (_, _, _, _, credits, _) = db_lock.get_license();

            if credits >= amount {
                let new_credits = credits - amount;
                let _ = db_lock.update_credits(new_credits);
                let _ = db_lock.add_ledger_entry(
                    &now_str(),
                    "Compute Task Execution (Simulated AI/Shader)",
                    &format!("-{} Credits", amount),
                    "CONFIRMED",
                );

                ui.set_available_credits(new_credits);
                let entries = db_lock.get_ledger();
                ui.set_ledger_entries(Rc::new(VecModel::from(entries)).into());

                ui.set_toast_title("⚡ Compute Task Executed".into());
                ui.set_toast_message(format!("Consumed {} units. Remaining: {} credits.", amount, new_credits).into());
                ui.set_toast_status("success".into());
                ui.set_toast_open(true);
            } else {
                ui.set_toast_title("⚠️ Insufficient Compute Units".into());
                ui.set_toast_message("You have depleted your available credits. Please top up to proceed.".into());
                ui.set_toast_status("danger".into());
                ui.set_toast_open(true);
            }
        });
    }

    // 2. Open Checkout Modal Trigger
    {
        let app_weak = app_handle.clone();
        app.on_open_checkout(move |plan_title, cycle, price| {
            let Some(ui) = app_weak.upgrade() else { return };
            ui.set_checkout_plan_title(plan_title);
            ui.set_checkout_billing_cycle(cycle);
            ui.set_checkout_plan_price(price);
            ui.set_checkout_crypto_step(0);
            ui.set_checkout_crypto_blocks(0);
            ui.set_checkout_feedback("".into());
            ui.set_checkout_open(true);
        });
    }

    // 3. Simulate India UPI Payment Webhook
    {
        let app_weak = app_handle.clone();
        let db = Arc::clone(&db);
        app.on_simulate_upi(move || {
            let Some(ui) = app_weak.upgrade() else { return };
            ui.set_checkout_feedback("UPI Webhook Received: ₹ Verified via HDFC Bank Gateway!".into());
            
            // Activate plan
            let title = ui.get_checkout_plan_title().to_string();
            let price = ui.get_checkout_plan_price().to_string();
            let db_lock = db.lock().unwrap();

            if title.contains("Pack") || title.contains("Credits") {
                let add_amt = if title.contains("25,000") { 25000 } else if title.contains("5,000") { 5000 } else { 1000 };
                let (_, _, _, _, cur_credits, cur_max) = db_lock.get_license();
                let _ = db_lock.update_credits(cur_credits + add_amt);
                let _ = db_lock.add_ledger_entry(&now_str(), &format!("Prepaid Credit Pack ({})", title), &format!("+{} Credits ({})", add_amt, price), "UPI_VERIFIED");
                ui.set_available_credits(cur_credits + add_amt);
                ui.set_max_credits(cur_max + add_amt);
            } else {
                let is_ent = title.contains("Enterprise");
                let plan_id = if is_ent { "enterprise" } else { "pro" };
                let plan_name = if is_ent { "Enterprise Studio" } else { "Pro Developer" };
                let key = if is_ent { "LIC-ED25519-ENT-8841-SCALE" } else { "LIC-ED25519-PRO-9482-DEV" };
                let max_c = if is_ent { 25000 } else { 5000 };
                let _ = db_lock.upgrade_plan(plan_id, plan_name, key, "2027-11-02 (365 Days)", max_c, max_c);
                let _ = db_lock.add_ledger_entry(&now_str(), &format!("Subscription Upgrade ({})", plan_name), &format!("{} (UPI Dynamic QR)", price), "UPI_VERIFIED");
                ui.set_active_plan(plan_id.into());
                ui.set_active_plan_name(plan_name.into());
                ui.set_license_key(key.into());
                ui.set_available_credits(max_c);
                ui.set_max_credits(max_c);
            }

            let entries = db_lock.get_ledger();
            ui.set_ledger_entries(Rc::new(VecModel::from(entries)).into());

            ui.set_toast_title("🇮🇳 UPI Payment Confirmed".into());
            ui.set_toast_message("Instant settlement confirmed via NPCI. License entitlement updated.".into());
            ui.set_toast_status("success".into());
            ui.set_toast_open(true);
        });
    }

    // 4. Simulate Non-Custodial Crypto Block Confirmation Sequence
    {
        let app_weak = app_handle.clone();
        let db = Arc::clone(&db);
        app.on_simulate_crypto(move || {
            let Some(ui) = app_weak.upgrade() else { return };
            ui.set_checkout_crypto_step(1); // Mempool
            ui.set_checkout_feedback("Tx 0x8f3c... broadcast detected in mempool. Waiting for block inclusion...".into());

            let app_tick = app_weak.clone();
            let db_tick = Arc::clone(&db);
            let mut tick_count = 0;

            let timer = Rc::new(slint::Timer::default());
            let timer_clone = Rc::clone(&timer);

            timer.start(slint::TimerMode::Repeated, Duration::from_millis(600), move || {
                let Some(ui) = app_tick.upgrade() else { return };
                tick_count += 1;

                if tick_count == 1 {
                    ui.set_checkout_crypto_step(2);
                    ui.set_checkout_crypto_blocks(4);
                    ui.set_checkout_feedback("Block confirmed (4/12). Validating state root on Polygon...".into());
                } else if tick_count == 2 {
                    ui.set_checkout_crypto_blocks(8);
                    ui.set_checkout_feedback("Block confirmed (8/12). Approaching finality...".into());
                } else if tick_count >= 3 {
                    ui.set_checkout_crypto_step(3);
                    ui.set_checkout_crypto_blocks(12);
                    ui.set_checkout_feedback("12/12 Blocks Finalized! On-Chain USDT Payment Verified.".into());

                    // Activate
                    let title = ui.get_checkout_plan_title().to_string();
                    let price = ui.get_checkout_plan_price().to_string();
                    let db_lock = db_tick.lock().unwrap();

                    if title.contains("Pack") || title.contains("Credits") {
                        let add_amt = if title.contains("25,000") { 25000 } else if title.contains("5,000") { 5000 } else { 1000 };
                        let (_, _, _, _, cur_credits, cur_max) = db_lock.get_license();
                        let _ = db_lock.update_credits(cur_credits + add_amt);
                        let _ = db_lock.add_ledger_entry(&now_str(), &format!("Prepaid Credit Pack ({})", title), &format!("+{} Credits ({})", add_amt, price), "ONCHAIN_USDT");
                        ui.set_available_credits(cur_credits + add_amt);
                        ui.set_max_credits(cur_max + add_amt);
                    } else {
                        let is_ent = title.contains("Enterprise");
                        let plan_id = if is_ent { "enterprise" } else { "pro" };
                        let plan_name = if is_ent { "Enterprise Studio" } else { "Pro Developer" };
                        let key = if is_ent { "LIC-ED25519-ENT-8841-SCALE" } else { "LIC-ED25519-PRO-9482-DEV" };
                        let max_c = if is_ent { 25000 } else { 5000 };
                        let _ = db_lock.upgrade_plan(plan_id, plan_name, key, "2027-11-02 (365 Days)", max_c, max_c);
                        let _ = db_lock.add_ledger_entry(&now_str(), &format!("Subscription Upgrade ({})", plan_name), &format!("{} (Polygon USDT)", price), "ONCHAIN_USDT");
                        ui.set_active_plan(plan_id.into());
                        ui.set_active_plan_name(plan_name.into());
                        ui.set_license_key(key.into());
                        ui.set_available_credits(max_c);
                        ui.set_max_credits(max_c);
                    }

                    let entries = db_lock.get_ledger();
                    ui.set_ledger_entries(Rc::new(VecModel::from(entries)).into());

                    ui.set_toast_title("⚡ Crypto Payment Finalized".into());
                    ui.set_toast_message("12 Polygon confirmations verified with zero private key exposure.".into());
                    ui.set_toast_status("success".into());
                    ui.set_toast_open(true);

                    timer_clone.stop();
                }
            });
        });
    }

    // 5. Complete Activation Trigger (Modal confirmation button)
    {
        let app_weak = app_handle.clone();
        app.on_complete_activation(move || {
            let Some(ui) = app_weak.upgrade() else { return };
            ui.set_checkout_open(false);
            ui.set_toast_title("License Key Activated".into());
            ui.set_toast_message("Asymmetric Ed25519 signature verified offline and stored in SQLite WAL.".into());
            ui.set_toast_status("success".into());
            ui.set_toast_open(true);
        });
    }

    // 6. Copy to Clipboard
    {
        let app_weak = app_handle.clone();
        app.on_copy_clipboard(move |text| {
            let Some(ui) = app_weak.upgrade() else { return };
            copy_to_clipboard(&text);
            ui.set_toast_title("Copied to Clipboard".into());
            ui.set_toast_message(text);
            ui.set_toast_status("info".into());
            ui.set_toast_open(true);
        });
    }

    // 7. Toggle Theme
    {
        app.on_toggle_theme(move || {
            // Slint Palette dark-mode toggle
        });
    }

    // 8. 1-Second Timer for Checkout Countdown & Heartbeat
    let timer_seconds = Rc::new(Mutex::new(14 * 60 + 59));
    let timer = slint::Timer::default();
    {
        let app_weak = app_handle.clone();
        let timer_seconds = Rc::clone(&timer_seconds);
        timer.start(slint::TimerMode::Repeated, Duration::from_secs(1), move || {
            let Some(ui) = app_weak.upgrade() else { return };
            let mut sec = timer_seconds.lock().unwrap();
            if *sec > 0 {
                *sec -= 1;
            } else {
                *sec = 15 * 60;
            }
            let m = *sec / 60;
            let s = *sec % 60;
            ui.set_checkout_timer_text(format!("{:02}:{:02}", m, s).into());
        });
    }

    println!("============================================================");
    println!("  DevBilling Studio — Desktop Commerce & Entitlements Hub   ");
    println!("============================================================");
    println!("  - Engine: Native Rust + Slint 1.9 Direct3D 12 (120 FPS)   ");
    println!("  - Database: Local Bundled SQLite WAL Mode (In-Process)    ");
    println!("  - Payment Rails: PCI-DSS Card, India UPI QR, Non-Custodial Crypto");
    println!("  - Zero Bloat: 0% Electron, 0% Node.js, Standalone Native  ");
    println!("============================================================");

    app.run()?;
    Ok(())
}

